describe("Cart – async checkout", () => {
  it("refreshes prices when priceFetcher is provided", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(1500);
  });

  it("uses original prices when priceFetcher is not provided", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("checks inventory and proceeds when available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "limited stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
      expect(invErr.message).toBe("limited stock");
    }
  });

  it("throws InventoryError for partial-stock denial (available=true but qty insufficient)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("generates default error message when reason is not provided", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).message).toContain("insufficient stock");
    }
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ discountPolicy, region: "US-CA" });
    cart.add(product("a", 10000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    // 10% of 10000 = 1000
    expect(result.totals.taxCents).toBe(1000);
  });

  it("applies discount before async tax", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(2000),
    };
    const cart = new Cart({ discountPolicy });
    cart.add(product("a", 10000), 1); // subtotal=10000, discount=2000, discounted=8000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // 10% of 8000 = 800
    expect(result.totals.taxCents).toBe(800);
    expect(result.totals.discountCents).toBe(2000);
  });

  it("includes shipping in async checkout totals", async () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.totals.shippingCents).toBe(599);
    expect(result.totals.totalCents).toBe(1000 + 599);
  });

  it("composes price refresh, discount, async tax, and shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "FR" });
    cart.add(product("a", 1000), 2); // original subtotal=2000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // refreshed subtotal: 1200 * 2 = 2400
    expect(result.totals.subtotalCents).toBe(2400);
    // discount=500, discounted=1900
    expect(result.totals.discountCents).toBe(500);
    // tax = 20% of 1900 = 380
    expect(result.totals.taxCents).toBe(380);
    expect(result.totals.shippingCents).toBe(300);
    // total = 1900 + 380 + 300 = 2580
    expect(result.totals.totalCents).toBe(2580);
  });

  it("checks inventory for each line and fails on first denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 3);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("propagates async tax provider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service unreachable")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service unreachable",
    );
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])(
    "returns 0 regardless of subtotal (%i)",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent (%s)",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent (%i)", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 = 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent (15% of 9999 = 1499.85 → 1499)", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(9999)).toBe(1499);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% returns the full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5050)).toBe(5050);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5050)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents (%i)", (amt) => {
      expect(() => new FixedAmountDiscountPolicy(amt)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(5000);
      expect(policy.computeDiscountCents(3000)).toBe(3000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amounts match", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe('sum mode (default)', () => {
    it("sums discounts from multiple policies against the original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("uses sum mode by default when mode is omitted", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(5000)).toBe(300);
    });

    it("can return more than subtotal (caller is responsible for clamping)", () => {
      // Two 60% discounts in sum mode = 120% — composite returns the raw sum.
      const p1 = new PercentageDiscountPolicy(60);
      const p2 = new PercentageDiscountPolicy(60);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // 60% of 1000 = 600, sum = 1200 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on the remaining subtotal", () => {
      // 10% of 10000 = 1000, then 500 fixed off remaining 9000 → total 1500
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("order matters: reversing policies changes the result", () => {
      // 500 fixed off 10000 = 500, then 10% of 9500 = 950 → total 1450
      const p1 = new FixedAmountDiscountPolicy(500);
      const p2 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1450);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const p1 = new FixedAmountDiscountPolicy(5000);
      const p2 = new FixedAmountDiscountPolicy(5000);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // first takes 3000 (min(5000,3000)), remaining=0, second gets 0
      expect(composite.computeDiscountCents(3000)).toBe(3000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

