+  describe("constructor validation", () => {
+    it("rejects empty brackets", () => {
+      expect(() => new WeightBasedShippingCalculator([])).toThrow(
+        "at least one weight bracket is required",
+      );
+    });
+
+    it("rejects bracket with zero upToGrams", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects bracket with negative upToGrams", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator([{ upToGrams: -5, costCents: 100 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects bracket with negative costCents", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer bracket values", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator([
+            { upToGrams: 500.5, costCents: 100 },
+          ]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects negative overflowCostCents", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator(
+            [{ upToGrams: 500, costCents: 100 }],
+            -1,
+          ),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer overflowCostCents", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator(
+            [{ upToGrams: 500, costCents: 100 }],
+            10.5,
+          ),
+      ).toThrow(RangeError);
+    });
+  });
+
+  describe("computeShippingCents", () => {
+    const calc = new WeightBasedShippingCalculator(
+      [
+        { upToGrams: 1000, costCents: 500 },
+        { upToGrams: 5000, costCents: 1200 },
+        { upToGrams: 500, costCents: 300 },  // intentionally out of order
+      ],
+      2000,
+    );
+
+    it("returns 0 for empty cart", () => {
+      expect(calc.computeShippingCents([], 5000)).toBe(0);
+    });
+
+    it("returns 0 when total weight is 0 (no weightGrams)", () => {
+      expect(
+        calc.computeShippingCents([makeLine("a", undefined, 2)], 5000),
+      ).toBe(0);
+    });
+
+    it("selects first bracket when weight is at its boundary", () => {
+      // 500g exactly → bracket upToGrams=500, cost=300
+      expect(
+        calc.computeShippingCents([makeLine("a", 500, 1)], 5000),
+      ).toBe(300);
+    });
+
+    it("selects first bracket when weight is below its boundary", () => {
+      expect(
+        calc.computeShippingCents([makeLine("a", 200, 1)], 5000),
+      ).toBe(300);
+    });
+
+    it("selects middle bracket when weight falls in range", () => {
+      // 700g → above 500, at or below 1000 → cost=500
+      expect(
+        calc.computeShippingCents([makeLine("a", 700, 1)], 5000),
+      ).toBe(500);
+    });
+
+    it("selects highest bracket at its boundary", () => {
+      // 5000g exactly → bracket upToGrams=5000, cost=1200
+      expect(
+        calc.computeShippingCents([makeLine("a", 2500, 2)], 5000),
+      ).toBe(1200);
+    });
+
+    it("uses overflow cost when weight exceeds all brackets", () => {
+      // 6000g > 5000 → overflow=2000
+      expect(
+        calc.computeShippingCents([makeLine("a", 3000, 2)], 5000),
+      ).toBe(2000);
+    });
+
+    it("defaults overflow to heaviest bracket cost when overflowCostCents is omitted", () => {
+      const noOverflow = new WeightBasedShippingCalculator([
+        { upToGrams: 1000, costCents: 500 },
+        { upToGrams: 2000, costCents: 800 },
+      ]);
+      // 3000g > 2000 → last bracket cost = 800
+      expect(
+        noOverflow.computeShippingCents([makeLine("a", 3000, 1)], 5000),
+      ).toBe(800);
+    });
+
+    it("accounts for quantity when computing weight", () => {
+      // 3 * 400g = 1200g → above 1000, at or below 5000 → cost=1200
+      expect(
+        calc.computeShippingCents([makeLine("a", 400, 3)], 5000),
+      ).toBe(1200);
+    });
+  });
+});
